/* ============================================================================
 * Winky Community - Game Plugin: Rigori (Penalty shootout)
 * Loaded on demand by the core (classic script, shares global scope).
 *
 * Styling: injects ONLY its own penalty-specific .pk* CSS. The shared arcade
 * chrome (jkptop/pips/jkpx/jkpend/timer) comes from the CORE stylesheet.
 *
 * CROSSPLAY CONTRACT (DO NOT CHANGE): reuses the same `game_challenges` table
 * as Jan Ken Pon. Game + challenger role are encoded in from_char ('pkK' =
 * keeper, 'pkA' = striker); directions reuse from_move/to_move; goals/saves
 * reuse from_score/to_score; turns reuse round. Keep this stable for the watch.
 * ==========================================================================*/
(function(){
  if(!document.getElementById('pk-css')){
    var s=document.createElement('style'); s.id='pk-css';
    s.textContent="  /* ===== Rigori (Penalty shootout) \u2014 pixel-art stadium (goal baked into bg) ===== */\n  .pk, .pk *{ -webkit-user-select:none !important; user-select:none !important; -webkit-touch-callout:none !important; -webkit-tap-highlight-color:transparent; }\n  .pkmoves button *{ pointer-events:none; }\n  .pkmoves button, .jkpx{ touch-action:manipulation; }\n  .pk{ position:fixed; inset:0; z-index:65; display:flex; flex-direction:column; overflow:hidden;\n    font-family:'Press Start 2P',monospace; color:#fff; image-rendering:pixelated; background:#0b1020; }\n  .pkstadium{ position:absolute; inset:0; width:100%; height:100%; display:block;\n    object-fit:cover; object-position:center center; image-rendering:pixelated;\n    transform-origin:center 45%; transition:filter .25s ease, transform .25s ease; }\n  .pkstadium.cheer{ animation:pkCheer .7s ease; }\n  @keyframes pkCheer{ 0%{filter:none;transform:scale(1)} 30%{filter:brightness(1.35) contrast(1.08) saturate(1.15); transform:scale(1.02)} 100%{filter:none; transform:scale(1)} }\n  .pkvignette{ position:absolute; inset:0; pointer-events:none;\n    background:radial-gradient(120% 80% at 50% 40%, transparent 60%, rgba(0,0,0,.4)),\n    linear-gradient(180deg, rgba(0,0,0,.18), transparent 16%); }\n  /* Full-screen stage: actors are positioned in screen space to match the goal\n     baked into the stadium image (see computeGeom in JS). */\n  .pkstage{ position:absolute; inset:0; z-index:4; pointer-events:none; overflow:hidden; }\n  .pkstage.shake{ animation:pkShake .38s ease; }\n  @keyframes pkShake{ 0%,100%{transform:translate(0,0)} 20%{transform:translate(-4px,2px)} 40%{transform:translate(4px,-2px)} 60%{transform:translate(-3px,1px)} 80%{transform:translate(3px,-1px)} }\n  /* Invisible goal box (JS positions it over the painted goal). Holds net flash + net ball. */\n  .pkgoal{ position:absolute; z-index:1; }\n  .pknetflash{ position:absolute; inset:0; background:rgba(255,255,255,0); }\n  .pknetflash.scored{ animation:pkNetFlash .5s ease; }\n  @keyframes pkNetFlash{ 0%{background:rgba(255,255,255,0)} 30%{background:rgba(255,255,255,.35)} 100%{background:rgba(255,255,255,0)} }\n  .pknetball{ position:absolute; width:14%; height:auto; z-index:3; opacity:0; image-rendering:pixelated; filter:drop-shadow(1px 2px 0 rgba(0,0,0,.4)); }\n  .pknetball.show{ opacity:1; animation:pkNetBall .35s ease; }\n  @keyframes pkNetBall{ 0%{transform:scale(.5)} 60%{transform:scale(1.15)} 100%{transform:scale(1)} }\n  /* Pixel-art players (dedicated Genoa/Sampdoria sprites). JS sets left/top/height. */\n  .pkkeeper{ position:absolute; z-index:4; transform-origin:50% 100%;\n    filter:drop-shadow(3px 5px 0 rgba(0,0,0,.5)); image-rendering:pixelated; will-change:transform; }\n  .pkkeeper.idle{ animation:pkKeeperIdle 1.1s ease-in-out infinite; }\n  @keyframes pkKeeperIdle{ 0%,100%{transform:translateX(-50%) rotate(0)} 25%{transform:translate(calc(-50% - 5px),-2px) rotate(-3deg)} 75%{transform:translate(calc(-50% + 5px),-2px) rotate(3deg)} }\n  .pkstriker{ position:absolute; z-index:5; transform-origin:50% 100%;\n    filter:drop-shadow(4px 6px 0 rgba(0,0,0,.5)); image-rendering:pixelated; will-change:transform; }\n  .pkstriker.idle{ animation:pkStrikerIdle 1.4s ease-in-out infinite; }\n  @keyframes pkStrikerIdle{ 0%,100%{transform:translateY(0)} 50%{transform:translateY(-5px)} }\n  .pkstriker.kick{ animation:pkKick .55s ease; }\n  @keyframes pkKick{ 0%{transform:translate(0,0) rotate(0)}\n    30%{transform:translate(18px,-8px) rotate(6deg)}\n    52%{transform:translate(30px,-2px) rotate(3deg) scale(1.05)}\n    74%{transform:translate(12px,0) rotate(-4deg)}\n    100%{transform:translate(0,0) rotate(0)} }\n  .pkball{ position:absolute; z-index:6; transform-origin:50% 50%; will-change:transform;\n    image-rendering:pixelated; filter:drop-shadow(2px 3px 0 rgba(0,0,0,.45)); }\n  .pkdust{ position:absolute; width:26px; height:14px; border-radius:50%; z-index:5;\n    background:radial-gradient(circle, rgba(255,255,255,.85), rgba(255,255,255,0) 70%); opacity:0; }\n  .pkdust.show{ animation:pkDust .5s ease; }\n  @keyframes pkDust{ 0%{opacity:0; transform:scale(.4)} 30%{opacity:.9; transform:scale(1)} 100%{opacity:0; transform:scale(1.6) translateY(-6px)} }\n  .pkresult{ position:absolute; inset:0; z-index:8; display:grid; place-items:center; pointer-events:none; }\n  .pkresult span{ font-size:12vw; text-shadow:4px 4px 0 #000; opacity:0; animation:jkppop2 .35s ease forwards; }\n  .pkresult span.goal{ color:#39d353; } .pkresult span.save{ color:#ffcf3f; }\n  .pkmoves{ position:absolute; left:0; right:0; bottom:calc(env(safe-area-inset-bottom,0px) + 26px); z-index:7; display:flex; gap:12px; justify-content:center; padding:8px 12px; }\n  .pkmoves button{ flex:1; max-width:110px; border:3px solid #000; background:#16233f; color:#fff; padding:12px 4px; border-radius:0; cursor:pointer; box-shadow:4px 4px 0 rgba(0,0,0,.5); font-family:'Press Start 2P',monospace; }\n  .pkmoves button .em{ font-size:34px; display:block; line-height:1; }\n  .pkmoves button:active{ transform:translate(2px,2px); box-shadow:2px 2px 0 rgba(0,0,0,.5); }\n  .pkmoves button.sel{ background:#e5484d; }\n  .pkmoves button:disabled{ opacity:.5; }\n  .pkstriker.kpov{ z-index:3 !important; }\n  .pkkeeper.kpov{ z-index:5 !important; }\n  .pkhint{ position:absolute; left:0; right:0; bottom:6px; z-index:7; text-align:center; font-size:9px; color:#ffe; padding:2px 12px; text-shadow:1px 1px 0 #000; }\n";
    document.head.appendChild(s);
  }
})();

/* ==================== Rigori (Penalty shootout) ==================== */
// Cross-play with the same game_challenges table used by Jan Ken Pon. To avoid
// any DB schema change, the game type + the challenger's RANDOM role are encoded
// in the existing from_char field: 'pkK' = challenger is Goalkeeper, 'pkA' =
// challenger is Striker. Directions (L/C/R) reuse from_move/to_move; goals/saves
// reuse from_score/to_score; turns reuse round (1..3).
const PK_DIRS=['L','C','R'];
const PK_ARROW={L:'\u25C0',C:'\u25B2',R:'\u25B6'};
const PK_SPR_STRIKER='data:image/png;base64,';
const PK_SPR_KEEPER='data:image/png;base64,';
const PK_SPR_BALL='data:image/png;base64,';
const PK_STADIUM='data:image/jpeg;base64,';
const PK_IMG_W=1000, PK_IMG_H=477;
const PK_GX0=0.3260, PK_GX1=0.6740, PK_GY0=0.2222, PK_GY1=0.3983;
const PK_GY_GRASS=0.4654;
/* ---- Keeper-POV assets (looking OUT from the goal toward the pitch) ---- */
const PK_STADIUM_KEEPER='data:image/jpeg;base64,';
const PK_KIMG_W=1000, PK_KIMG_H=667;      // keeper-POV background natural size
const PK_K_SPOT_X=0.5, PK_K_SPOT_Y=0.45;  // where the distant striker + ball start
// Directional sprites for the keeper POV. Placeholders map to the existing
// sprites until the dedicated back-view keeper / front-view striker art is in.
const PK_SPR_KEEPER_BACK_ART='data:image/png;base64,';
const PK_SPR_STRIKER_FRONT_ART='data:image/png;base64,';
const PK_SPR_KEEPER_BACK   = (typeof PK_SPR_KEEPER_BACK_ART!=='undefined')   ? PK_SPR_KEEPER_BACK_ART   : PK_SPR_KEEPER;
const PK_SPR_STRIKER_FRONT = (typeof PK_SPR_STRIKER_FRONT_ART!=='undefined') ? PK_SPR_STRIKER_FRONT_ART : PK_SPR_STRIKER;
function isPkChar(fc){ return !!fc && String(fc).indexOf('pk')===0; }

async function openPenaltyChallenge(threadId, otherId, otherNick){
  const fromKeeper = Math.random()<0.5; // role assigned at RANDOM
  try{
    const row=await insert('/game_challenges',{thread_id:threadId,from_id:App.me.id,from_nick:App.me.nickname,to_id:otherId,to_nick:otherNick,from_char:(fromKeeper?'pkK':'pkA'),status:'pending',round:1,from_score:0,to_score:0});
    const ch=row&&row.length?row[0]:null;
    if(ch){ App.go('pkGame',{id:ch.id,role:'from',otherNick:otherNick,iAmKeeper:fromKeeper}); }
  }catch(e){ toast('Error: '+e.message); }
}
async function acceptPenaltyChallenge(ch){
  try{ await rest('/game_challenges?id=eq.'+ch.id,{method:'PATCH',body:{status:'active',round:1,updated_at:new Date().toISOString()}}); App.go('pkGame',{id:ch.id,role:'to',otherNick:ch.from_nick,iAmKeeper:(String(ch.from_char||'pkA')!=='pkK')}); }catch(e){ toast('Error'); }
}
// ---- The penalty arena ----
views.pkGame=function(p){
  const meFrom=p.role==='from';
  const POV = p.iAmKeeper ? 'keeper' : 'attacker';   // which perspective to render
  let ch=null; let curRound=0; let myMove=null; let animating=false; let phaseResolved=false; let ended=false;
  let tLeft=15; let tInt=null;
  const m=App.main(); m.classList.remove('chatview');
  const root=el('div','pk');
  // Stadium image with the goal + crowd + ads baked in, at correct ground perspective.
  const stad=document.createElement('img'); stad.className='pkstadium'; stad.src=(POV==='keeper'?PK_STADIUM_KEEPER:PK_STADIUM); root.appendChild(stad);
  const vig=el('div','pkvignette'); root.appendChild(vig);
  const xb=el('button','jkpx','\u2715'); xb.onclick=()=>{ finishExit(); }; root.appendChild(xb);
  // top bar (reuses jkp top styles)
  const top=el('div','jkptop');
  const sideL=el('div','side l'); const pnL=el('div','pn'); const roL=el('div','pkrole'); const pipsL=el('div','pips'); sideL.appendChild(pnL); sideL.appendChild(roL); sideL.appendChild(pipsL);
  const rnd=el('div','rnd','ROUND 1');
  const sideR=el('div','side r'); const pnR=el('div','pn'); const roR=el('div','pkrole'); const pipsR=el('div','pips'); sideR.appendChild(pnR); sideR.appendChild(roR); sideR.appendChild(pipsR);
  top.appendChild(sideL); top.appendChild(rnd); top.appendChild(sideR); root.appendChild(top);
  // timer
  const timer=el('div','jkptimer'); const tfill=el('i'); timer.appendChild(tfill); root.appendChild(timer);
  // Full-screen stage holding all actors, aligned to the baked goal via computeGeom.
  const stage=el('div','pkstage');
  const goal=el('div','pkgoal');
  const netFlash=el('div','pknetflash'); goal.appendChild(netFlash);
  const netBall=document.createElement('img'); netBall.className='pknetball'; netBall.src=PK_SPR_BALL; goal.appendChild(netBall);
  stage.appendChild(goal);
  const keeper=document.createElement('img'); keeper.className='pkkeeper idle'+(POV==='keeper'?' kpov':''); keeper.src=(POV==='keeper'?PK_SPR_KEEPER_BACK:PK_SPR_KEEPER); stage.appendChild(keeper);
  const striker=document.createElement('img'); striker.className='pkstriker idle'+(POV==='keeper'?' kpov':''); striker.src=(POV==='keeper'?PK_SPR_STRIKER_FRONT:PK_SPR_STRIKER); stage.appendChild(striker);
  const ball=document.createElement('img'); ball.className='pkball'; ball.src=PK_SPR_BALL; stage.appendChild(ball);
  const dust=el('div','pkdust'); stage.appendChild(dust);
  root.appendChild(stage);
  // result overlay
  const resultOv=el('div','pkresult'); root.appendChild(resultOv);
  // moves: left / center / right
  const moves=el('div','pkmoves');
  const mkMove=(k)=>{ const b=el('button'); b.innerHTML='<span class="em">'+PK_ARROW[k]+'</span>'; b.dataset.k=k; b.addEventListener('contextmenu',e=>e.preventDefault()); b.onclick=()=>pickMove(k); return b; };
  const bL=mkMove('L'), bC=mkMove('C'), bR=mkMove('R');
  moves.appendChild(bL); moves.appendChild(bC); moves.appendChild(bR); root.appendChild(moves);
  const hint=el('div','pkhint'); root.appendChild(hint);
  const wait=el('div','jkpwait'); wait.style.display='none'; root.appendChild(wait);
  const endOv=el('div','jkpend'); endOv.style.display='none'; root.appendChild(endOv);
  m.appendChild(root);

  // ---- Geometry: align the invisible goal box + actors to the painted goal ----
  // Image natural size + goal fractions (measured from the artwork).
  const IMG_W=PK_IMG_W, IMG_H=PK_IMG_H, GX0=PK_GX0, GX1=PK_GX1, GY0=PK_GY0, GY1=PK_GY1;
  let geom=null;
  // ---- Geometry dispatcher: attacker looks AT the goal, keeper looks OUT ----
  function computeGeom(){ if(POV==='keeper') return computeGeomKeeper(); return computeGeomAttacker(); }
  function computeGeomAttacker(){
    const sw=stage.clientWidth, sh=stage.clientHeight; if(!sw||!sh) return;
    const scale=Math.max(sw/IMG_W, sh/IMG_H);   // object-fit: cover
    const dW=IMG_W*scale, dH=IMG_H*scale;
    const ox=(sw-dW)*0.5, oy=(sh-dH)*0.5;         // object-position: center center
    const gx0=ox+GX0*dW, gx1=ox+GX1*dW, gy0=oy+GY0*dH, gy1=oy+GY1*dH;
    const gw=gx1-gx0, gh=gy1-gy0, gcx=(gx0+gx1)/2;
    goal.style.left=gx0+'px'; goal.style.top=gy0+'px'; goal.style.width=gw+'px'; goal.style.height=gh+'px';
    const refW=Math.min(gw, sw*0.94);
    const goalLineY=gy1;
    const grassY=oy+PK_GY_GRASS*dH;
    const kH=refW*0.36; keeper.style.height=kH+'px'; keeper.style.left=gcx+'px'; keeper.style.top=(grassY-kH)+'px';
    const stH=refW*0.58; const stX=gcx - refW*0.42;
    const stFeet=Math.min(sh*0.99, grassY + refW*0.80);
    striker.style.height=stH+'px'; striker.style.bottom='auto';
    striker.style.left=stX+'px'; striker.style.top=(stFeet-stH)+'px';
    const bw=Math.max(14, refW*0.11); ball.style.width=bw+'px'; ball.style.height='auto';
    const spotX=gcx - refW*0.16, spotY=stFeet - refW*0.02;
    ball.style.left=spotX+'px'; ball.style.top=(spotY-bw)+'px';
    dust.style.left=(spotX-14)+'px'; dust.style.top=(spotY-6)+'px';
    geom={mode:'attacker',gcx,gw,gh,gy0,gy1,goalLineY,refW,spotX,spotY,bw,stFeet};
  }
  // Keeper POV: YOU are the big keeper (from behind) in the foreground; the
  // striker is far away facing you on the penalty spot; the ball flies TOWARD
  // the camera (grows) when struck.
  function computeGeomKeeper(){
    const sw=stage.clientWidth, sh=stage.clientHeight; if(!sw||!sh) return;
    const scale=Math.max(sw/PK_KIMG_W, sh/PK_KIMG_H);
    const dW=PK_KIMG_W*scale, dH=PK_KIMG_H*scale;
    const ox=(sw-dW)*0.5, oy=(sh-dH)*0.5;
    const refW=Math.min(dW, sw*0.98);
    // Size everything from the stadium's displayed HEIGHT (dH), not screen width.
    // On wide PC screens refW=sw*0.98 exploded, making the distant striker huge and
    // centred over the keeper. dH tracks the pitch, so proportions stay correct on
    // any aspect ratio (this is why the bug only appeared on desktop).
    const unit=dH;
    const spotX=ox+PK_K_SPOT_X*dW, spotY=oy+PK_K_SPOT_Y*dH;
    // Distant striker facing the camera: SMALL and offset RIGHT of the spot, a
    // touch higher (= farther), to sell the from-behind-the-goal perspective.
    const stH=unit*0.20; const stAsp=(striker.naturalWidth&&striker.naturalHeight)?(striker.naturalWidth/striker.naturalHeight):0.6; const stW=stH*stAsp;
    const stX=spotX + unit*0.10, stFeet=spotY - unit*0.02;
    striker.style.height=stH+'px'; striker.style.bottom='auto'; striker.style.left=(stX - stW/2)+'px'; striker.style.top=(stFeet-stH)+'px';
    // Ball on the penalty spot. HIDDEN at rest in keeper POV (perspective would put
    // it on the keeper's head); shown only when the shot flies (see flyBallKeeper).
    const bw=Math.max(9, unit*0.05); ball.style.width=bw+'px'; ball.style.height='auto';
    ball.style.left=(spotX - bw/2)+'px'; ball.style.top=(spotY-bw*0.5)+'px'; ball.style.opacity='0';
    // Foreground keeper (seen from behind), big but capped so it doesn't fill the
    // whole desktop screen and cover the striker.
    const kH=Math.min(unit*0.62, sh*0.72); keeper.style.height=kH+'px'; keeper.style.left=(sw*0.5)+'px';
    const kFeet=sh*1.04; keeper.style.top=(kFeet-kH)+'px';
    dust.style.left=(spotX-14)+'px'; dust.style.top=(spotY-6)+'px';
    geom={mode:'keeper',sw,sh,refW,spotX,spotY,bw,kH,kFeet};
  }
  if(window.__pkResize){ try{ window.removeEventListener('resize',window.__pkResize); }catch(e){} }
  window.__pkResize=computeGeom; window.addEventListener('resize',window.__pkResize);
  const relayout=()=>{ computeGeom(); resetActors(); };
  stad.addEventListener('load',relayout);

  // Roles are fixed for the match, derived from from_char (resolved each tick).
  let fromIsKeeper=true;
  const iAmKeeper=()=> meFrom? fromIsKeeper : !fromIsKeeper;
  const myScoreOf=(r)=> meFrom? r.from_score : r.to_score;
  const opScoreOf=(r)=> meFrom? r.to_score : r.from_score;
  const myMoveField=()=> meFrom?'from_move':'to_move';
  const myMoveOf=(r)=> meFrom? r.from_move : r.to_move;
  const opMoveOf=(r)=> meFrom? r.to_move : r.from_move;

  const setPips=(a,b)=>{ const draw=(n,box)=>{ box.innerHTML=''; for(let i=0;i<3;i++){ const s=el('span','pip'+(i<n?' on':'')); box.appendChild(s);} }; draw(a,pipsL); draw(b,pipsR); };
  const setRoles=()=>{ const mk=iAmKeeper(); roL.textContent=mk?('\uD83E\uDDE4 '+T('roleKeeperShort')):('\u26BD '+T('roleAttackerShort')); roR.textContent=mk?('\u26BD '+T('roleAttackerShort')):('\uD83E\uDDE4 '+T('roleKeeperShort')); hint.textContent=mk?T('pkDiveHint'):T('pkShootHint'); };
  const setMovesEnabled=(on)=>{ [bL,bC,bR].forEach(b=>{ b.disabled=!on; b.classList.remove('sel'); }); moves.style.display=on?'flex':'none'; hint.style.display=on?'block':'none'; wait.style.display=on?'none':'block'; if(!on){ wait.textContent=T('waitOpponent'); } };

  function resetActors(){
    ball.style.transition='none'; ball.style.transform='translateX(-50%) rotate(0deg)';
    // Keeper POV: keep the ball hidden at rest (it would sit on the keeper's head
    // due to perspective). It's revealed the instant the shot flies. Attacker POV:
    // the ball at the striker's feet is correct, so show it.
    ball.style.opacity=(POV==='keeper')?'0':'1';
    keeper.style.transition='none'; keeper.classList.add('idle'); keeper.style.transform='';
    striker.classList.remove('kick'); striker.classList.add('idle'); striker.style.transform='';
    netFlash.classList.remove('scored'); netBall.classList.remove('show'); netBall.style.opacity='0';
    dust.classList.remove('show'); stad.classList.remove('cheer'); stage.classList.remove('shake');
    void ball.offsetWidth;
  }
  const dirOffset=(dir,w)=> (dir==='L'?-1:dir==='R'?1:0)*w*0.30;
  // Ball flies from the penalty spot up into the goal mouth (depth scale + spin).
  function flyBall(dir,saved){ if(POV==='keeper') return flyBallKeeper(dir,saved); return flyBallAttacker(dir,saved); }
  // Attacker POV: ball flies AWAY from the camera up into the goal (shrinks).
  function flyBallAttacker(dir,saved){
    if(!geom) computeGeom();
    const gcx=geom.gcx, gy=geom.gy0+geom.gh*0.55;
    const br=ball.getBoundingClientRect(); const st=stage.getBoundingClientRect();
    const bx=br.left+br.width/2-st.left, by=br.top+br.height/2-st.top;
    const tx=(gcx+dirOffset(dir,geom.refW))-bx, ty=gy-by;
    ball.style.transition='transform .5s cubic-bezier(.2,.7,.3,1)';
    ball.style.transform='translate(calc(-50% + '+tx+'px),'+ty+'px) scale(.5) rotate(700deg)';
    if(saved){
      setTimeout(()=>{ const s=(dir==='L'?-1:dir==='R'?1:0); const rx=tx - s*geom.refW*0.55 - 20; const ry=ty+geom.gh*1.1;
        ball.style.transition='transform .5s cubic-bezier(.3,.2,.2,1)';
        ball.style.transform='translate(calc(-50% + '+rx+'px),'+ry+'px) scale(.85) rotate(-360deg)'; },420);
    }
  }
  // Keeper POV: ball flies TOWARD the camera (grows) to L/C/R past the keeper.
  function flyBallKeeper(dir,saved){
    if(!geom) computeGeom();
    ball.style.opacity='1'; // reveal the ball now that the shot is being taken
    const st=stage.getBoundingClientRect(); const br=ball.getBoundingClientRect();
    const bx=br.left+br.width/2-st.left, by=br.top+br.height/2-st.top;
    const tX=geom.sw*(dir==='L'?0.30:dir==='R'?0.70:0.5), tY=geom.sh*0.88;
    const tx=tX-bx, ty=tY-by;
    ball.style.transition='transform .5s cubic-bezier(.35,.55,.4,1)';
    ball.style.transform='translate(calc(-50% + '+tx+'px),'+ty+'px) scale(4.6) rotate(760deg)';
    if(saved){
      setTimeout(()=>{ const s=(dir==='L'?-1:dir==='R'?1:0); const rx=tx - s*geom.sw*0.12; const ry=ty - geom.sh*0.30;
        ball.style.transition='transform .45s cubic-bezier(.3,.2,.2,1)';
        ball.style.transform='translate(calc(-50% + '+rx+'px),'+ry+'px) scale(2.8) rotate(-320deg)'; },380);
    }
  }
  function diveKeeper(dir){ if(POV==='keeper') return diveKeeperKeeper(dir); return diveKeeperAttacker(dir); }
  // Attacker POV: small distant keeper on the goal line dives.
  function diveKeeperAttacker(dir){
    keeper.classList.remove('idle');
    keeper.style.transition='transform .42s cubic-bezier(.2,.7,.3,1)';
    if(dir==='C'){ keeper.style.transform='translate(-50%,-12px) scale(1.12,1.02)'; }
    else { const tx=dirOffset(dir,geom.refW)*0.85; const rot=(dir==='L'?-52:52);
      keeper.style.transform='translate(calc(-50% + '+tx+'px),2px) rotate('+rot+'deg) scale(1.05,.92)'; }
  }
  // Keeper POV: big foreground keeper throws himself L/C/R.
  function diveKeeperKeeper(dir){
    keeper.classList.remove('idle');
    keeper.style.transition='transform .40s cubic-bezier(.2,.7,.3,1)';
    if(dir==='C'){ keeper.style.transform='translate(-50%,-8px) scale(1.05)'; }
    else { const s=(dir==='L'?-1:1); const tx=s*(geom.sw*0.24); const rot=s*20;
      keeper.style.transform='translate(calc(-50% + '+tx+'px),-6px) rotate('+rot+'deg) scale(1.04)'; }
  }
  function goalEffects(dir){ if(POV==='keeper') return goalEffectsKeeper(dir); return goalEffectsAttacker(dir); }
  function goalEffectsAttacker(dir){
    const cxPct = dir==='L'?26:dir==='R'?62:44;   // % within the goal box
    netBall.style.left=cxPct+'%'; netBall.style.top='42%';
    netFlash.classList.add('scored'); netBall.classList.add('show'); stad.classList.add('cheer');
  }
  // Keeper POV: no goal box on-screen; flash the whole pitch + shake + cheer.
  function goalEffectsKeeper(dir){
    if(geom&&geom.sw){ goal.style.left='0px'; goal.style.top='0px'; goal.style.width=geom.sw+'px'; goal.style.height=geom.sh+'px'; }
    netFlash.classList.add('scored'); stad.classList.add('cheer'); stage.classList.add('shake');
  }

  const startTimer=()=>{ stopTimer(); tLeft=15; tfill.style.width='100%'; tInt=setInterval(()=>{ tLeft-=0.25; if(tLeft<=0){ tLeft=0; tfill.style.width='0%'; stopTimer(); if(!myMove&&!animating&&!ended){ pickMove(PK_DIRS[Math.floor(Math.random()*3)]); } } else { tfill.style.width=(tLeft/15*100)+'%'; } },250); App.poll2=tInt; };
  const stopTimer=()=>{ if(tInt){ clearInterval(tInt); if(App.poll2===tInt)App.poll2=null; tInt=null; } };

  async function pickMove(k){ if(myMove||animating||ended) return; myMove=k; [bL,bC,bR].forEach(b=>{ if(b.dataset.k===k)b.classList.add('sel'); b.disabled=true; }); stopTimer(); wait.style.display='block'; wait.textContent=T('waitOpponent'); moves.style.display='none'; hint.style.display='none'; try{ const body={updated_at:new Date().toISOString()}; body[myMoveField()]=k; await rest('/game_challenges?id=eq.'+p.id,{method:'PATCH',body}); }catch(e){} }

  async function resolveTurn(r){
    const myK=myMoveOf(r), opK=opMoveOf(r); if(!myK||!opK) return;
    phaseResolved=true; animating=true; stopTimer(); setMovesEnabled(false);
    const keeperMove = fromIsKeeper? r.from_move : r.to_move;
    const attackerMove = fromIsKeeper? r.to_move : r.from_move;
    const saved = (attackerMove===keeperMove);
    resetActors(); computeGeom();
    striker.classList.remove('idle'); void striker.offsetWidth; striker.classList.add('kick');
    setTimeout(()=>{ dust.classList.add('show'); stage.classList.add('shake'); }, 150);
    setTimeout(()=>{ flyBall(attackerMove,saved); diveKeeper(keeperMove); }, 300);
    setTimeout(()=>{
      if(!saved) goalEffects(attackerMove);
      resultOv.innerHTML=''; const sp=el('span', saved?'save':'goal', saved?('\uD83E\uDDE4 '+T('pkSave')):('\u26BD '+T('pkGoal'))); resultOv.appendChild(sp);
      setTimeout(async()=>{
        resultOv.innerHTML=''; resetActors();
        if(meFrom){
          let fs=r.from_score, ts=r.to_score;
          if(saved){ if(fromIsKeeper) fs++; else ts++; }
          else{ if(fromIsKeeper) ts++; else fs++; }
          let status='active', winner=null, nextRound=r.round+1;
          if(r.round>=3){ status='finished'; winner = fs>ts? p.__fromId : (ts>fs? p.__toId : 0); }
          try{ await rest('/game_challenges?id=eq.'+p.id,{method:'PATCH',body:{from_score:fs,to_score:ts,round:(status==='finished'?r.round:nextRound),from_move:null,to_move:null,winner:winner,status:status,updated_at:new Date().toISOString()}}); }catch(e){}
        }
        animating=false; myMove=null;
      },1300);
    },1050);
  }

  let rematchPoll=null; let rematchShown=0;
  function renderEnd(r){ const iWon=(r.winner===App.me.id); const draw=(r.winner===0||r.winner==null); endOv.innerHTML=''; const big=el('div','big '+(draw?'draw':(iWon?'win':'lose')), draw?'DRAW':(iWon?T('youWin'):T('youLose'))); endOv.appendChild(big); const sub=el('div',null, T('pkFinal')+' '+myScoreOf(r)+' - '+opScoreOf(r)); sub.style.fontSize='11px'; sub.style.textShadow='2px 2px 0 #000'; endOv.appendChild(sub); const row=el('div'); row.style.display='flex'; row.style.gap='12px'; const again=el('button','green',T('rematch')); again.onclick=()=>{ cleanup(); App.back(); setTimeout(()=>openPenaltyChallenge(p.__threadId,(meFrom?p.__toId:p.__fromId),p.otherNick),150); }; const back=el('button',null,T('exit')); back.onclick=()=>{ cleanup(); App.back(); }; row.appendChild(again); row.appendChild(back); endOv.appendChild(row); endOv.style.display='flex'; }
  function renderRematchIncoming(nc){ endOv.innerHTML=''; const t=el('div','big win','\u26BD'); t.style.fontSize='16vw'; endOv.appendChild(t); const msg=el('div',null,(nc.from_nick||p.otherNick)+' '+T('rematchIncoming')); msg.style.fontSize='10px'; msg.style.textAlign='center'; msg.style.textShadow='2px 2px 0 #000'; endOv.appendChild(msg); const row=el('div'); row.style.display='flex'; row.style.gap='12px'; const acc=el('button','green',T('accept')); acc.onclick=()=>{ cleanup(); App.back(); setTimeout(()=>acceptPenaltyChallenge(nc),150); }; const dec=el('button',null,T('reject')); dec.onclick=async()=>{ try{ await rest('/game_challenges?id=eq.'+nc.id,{method:'PATCH',body:{status:'declined',updated_at:new Date().toISOString()}}); }catch(e){} rematchShown=0; renderEnd(ch); }; row.appendChild(acc); row.appendChild(dec); endOv.appendChild(row); }
  function stopRematchPoll(){ if(rematchPoll){ clearInterval(rematchPoll); rematchPoll=null; } }
  function cleanup(){ stopRematchPoll(); if(window.__pkResize){ try{ window.removeEventListener('resize',window.__pkResize); }catch(e){} window.__pkResize=null; } }
  function showEnd(r){ ended=true; App.stopPoll(); setMovesEnabled(false); wait.style.display='none'; hint.style.display='none'; renderEnd(r); const oppId=meFrom?p.__toId:p.__fromId; stopRematchPoll(); rematchPoll=setInterval(async()=>{ try{ const rows=await rest('/game_challenges?to_id=eq.'+App.me.id+'&from_id=eq.'+oppId+'&status=eq.pending&order=id.desc&limit=1'); const nc=rows&&rows.length?rows[0]:null; if(nc && nc.id!==p.id && isPkChar(nc.from_char)){ if(rematchShown!==nc.id){ rematchShown=nc.id; renderRematchIncoming(nc); } } else { if(rematchShown){ rematchShown=0; renderEnd(ch); } } }catch(e){} },1500); App.poll2=rematchPoll; }
  async function finishExit(){ cleanup(); App.stopPoll(); try{ if(!ended){ await rest('/game_challenges?id=eq.'+p.id,{method:'PATCH',body:{status:'finished',winner:(meFrom?p.__toId:p.__fromId),updated_at:new Date().toISOString()}}); } }catch(e){} App.back(); }

  async function tick(){
    try{ const rows=await rest('/game_challenges?id=eq.'+p.id+'&select=*'); const r=rows&&rows.length?rows[0]:null; if(!r) return; ch=r;
      p.__fromId=r.from_id; p.__toId=r.to_id; p.__threadId=r.thread_id;
      fromIsKeeper = String(r.from_char||'pkA')==='pkK';
      pnL.textContent=(App.me.nickname||'You'); pnR.textContent= meFrom? (r.to_nick||p.otherNick) : (r.from_nick||p.otherNick);
      setRoles(); setPips(myScoreOf(r), opScoreOf(r)); rnd.textContent='ROUND '+Math.min(r.round,3);
      if(r.status==='declined'){ if(!ended){ ended=true; toast(T('declinedGame')); setTimeout(()=>App.back(),800);} return; }
      if(r.status==='finished'){ if(!ended) showEnd(r); return; }
      if(r.status!=='active'){ wait.style.display='block'; wait.textContent=T('waitAccept'); moves.style.display='none'; hint.style.display='none'; return; }
      const myK=myMoveOf(r), opK=opMoveOf(r);
      if(r.round!==curRound){ curRound=r.round; myMove=null; animating=false; phaseResolved=false; resetActors(); resultOv.innerHTML=''; }
      if(!myK && !opK && !animating && !ended){ if(phaseResolved || myMove!==null || moves.style.display!=='flex'){ phaseResolved=false; myMove=null; resetActors(); resultOv.innerHTML=''; setMovesEnabled(true); startTimer(); } }
      if(myK){ if(myMove!==myK) myMove=myK; setMovesEnabled(false); }
      if(myK && !opK && !animating){ wait.style.display='block'; wait.textContent=T('waitOpponent'); moves.style.display='none'; hint.style.display='none'; }
      if(myK && opK && !animating && !phaseResolved){ resolveTurn(r); }
    }catch(e){}
  }
  // Initial geometry (retry a few frames for layout/safe-area settling).
  computeGeom(); resetActors();
  requestAnimationFrame(()=>{ computeGeom(); resetActors(); });
  setTimeout(()=>{ computeGeom(); resetActors(); },120);
  setMovesEnabled(false); wait.style.display='block'; wait.textContent= meFrom? T('waitAccept'): T('getReady');
  App.stopPoll(); tick(); App.poll=setInterval(tick,1000);
};


/* ---- register with the core ---- */
if(window.WinkyGames){ WinkyGames.register({
  id:'rigori',
  openChallenge:function(threadId,otherId,otherNick){ return openPenaltyChallenge(threadId,otherId,otherNick); },
  acceptChallenge:function(ch){ return acceptPenaltyChallenge(ch); },
  challengeIcon:function(ch){ var d=el('div',null,'\u26BD'); d.style.fontSize='40px'; d.style.width='46px'; d.style.textAlign='center'; return d; }
}); }
